class Solution {
    public: vector<int> luckyNumbers(vector<vector<int>>& matrix){
        int rows=matrix.size(),cols=matrix[0].size();
        vector<int> rowMin(rows,INT_MAX),colMax(cols,INT_MIN);
        for(int row=0;row<rows;++row)for(int col=0;col<cols;++col){
            rowMin[row]=min(rowMin[row],matrix[row][col]);
            colMax[col]=max(colMax[col],matrix[row][col]);
        }
        vector<int> answer;
        for(int row=0;row<rows;++row)for(int col=0;col<cols;++col)if(matrix[row][col]==rowMin[row]&&matrix[row][col]==colMax[col])answer.push_back(matrix[row][col]);
        return answer;
    }
};
